package com.bitedash.service; import com.bitedash.dto.*; import com.bitedash.entity.*; import com.bitedash.exception.*; import com.bitedash.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.util.*; @Service public class OrderService {private final OrderRepository orders; private final UserRepository users; private final FoodItemRepository foods; public OrderService(OrderRepository o,UserRepository u,FoodItemRepository f){orders=o;users=u;foods=f;} private User user(Long id){return users.findById(id).orElseThrow(()->new NotFoundException("User not found"));} @Transactional public OrderResponse create(Long uid,CreateOrderRequest r){User u=user(uid); BigDecimal total=BigDecimal.ZERO; List<FoodItem> selected=new ArrayList<>(); for(OrderItemRequest x:r.items()){FoodItem f=foods.findById(x.foodItemId()).orElseThrow(()->new NotFoundException("Food item not found: "+x.foodItemId())); if(!f.isAvailable())throw new BadRequestException("Food item is unavailable: "+f.getName()); selected.add(f); total=total.add(f.getPrice().multiply(BigDecimal.valueOf(x.quantity())));} Order o=new Order(u,r.deliveryAddress().trim(),total); for(int i=0;i<r.items().size();i++)o.addItem(new OrderItem(o,selected.get(i),r.items().get(i).quantity())); return OrderResponse.of(orders.save(o));} @Transactional(readOnly=true) public List<OrderResponse> list(Long uid){user(uid);return orders.findByUserIdOrderByOrderedAtDesc(uid).stream().map(OrderResponse::of).toList();} @Transactional public OrderResponse cancel(Long uid,Long id){Order o=orders.findById(id).orElseThrow(()->new NotFoundException("Order not found"));if(!o.getUser().getId().equals(uid))throw new BadRequestException("You cannot modify this order");if(o.getStatus()!=OrderStatus.PLACED&&o.getStatus()!=OrderStatus.CONFIRMED)throw new BadRequestException("Order can no longer be cancelled");o.cancel();return OrderResponse.of(o);}}
